template<typename T>
using Iterator = typename T::iterator; // T의 반복자

template<typename C, typename V>
vector<Iterator<C>> find_all(C& c, V v) // c에서 v가 나타나는 곳을 모두 찾기
{
    vector<Iterator<C>> res;
    for (auto p = c.begin(); p!=c.end(); ++p)
        if (*p==v)
            res.push_back(p);
    return res;
}

